use aap::caps::http_client;
use aap::caps::notifier;

struct Node;

/// Percent-encode a value for use as a URL query component, so input text
/// cannot inject extra parameters or path segments into the enrichment URL.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch for this input. `fetch` returns transport failures
        // as values; the result is deliberately discarded so the output does
        // not depend on it. Note: `Digest` has no `text` field, so the digest's
        // `overview` is used as the input's text.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&composed.overview)
        );
        let _ = http_client::fetch(&url);

        let message = format!("{}: {}", composed.date, composed.overview);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
